// Copies the shared money fixtures from the iOS repo (the canonical copy, generated by
// SplitSwift/Tools/money-fixtures/generate.py) into src/lib/__fixtures__/.
//   node scripts/sync-money-fixtures.mjs [path/to/SplitSwift]
// Default iOS repo location: ~/Desktop/Projects/Apps/OnlyBills/SplitSwift
import { copyFileSync, readFileSync, existsSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const iosRepo = process.argv[2] || join(homedir(), 'Desktop/Projects/Apps/OnlyBills/SplitSwift');
const source = join(iosRepo, 'SplitSwiftTests/Fixtures/Money/money-cases.json');
const target = join(here, '../src/lib/__fixtures__/money-cases.json');

if (!existsSync(source)) {
  console.error(`No fixtures at ${source} — pass the SplitSwift repo path.`);
  process.exit(1);
}
const before = existsSync(target) ? readFileSync(target, 'utf8') : '';
copyFileSync(source, target);
const after = readFileSync(target, 'utf8');
console.log(before === after ? 'money fixtures already in sync' : `money fixtures updated from ${source}`);
